    format: { page: { width: 130, height: 196, top: 5, bottom: 5, left: 10, right: 10, header: 10, footer: 10, gutter: 0 }, font: '바탕', roles: { title: { size: 14, bold: true, align: 'center', lineSpacing: 140, ratio: 90, spacing: -5 }, author: { size: 11, align: 'right', lineSpacing: 160, ratio: 90, spacing: -5 }, affiliation: { size: 10, align: 'right', lineSpacing: 160, ratio: 90, spacing: -5 }, abstractEn: { size: 8, align: 'justify', lineSpacing: 130, ratio: 90, spacing: -5 }, keywordsEn: { size: 8, bold: true, align: 'justify', lineSpacing: 130, ratio: 90, spacing: -5 }, keywords: { size: 8, bold: true, align: 'justify', lineSpacing: 130, ratio: 90, spacing: -5 }, h1: { size: 12, bold: true, align: 'center', lineSpacing: 160, ratio: 90, spacing: -5 }, h2: { size: 11, align: 'left', lineSpacing: 160, ratio: 90, spacing: -5 }, h3: { size: 10, align: 'left', lineSpacing: 160, ratio: 90, spacing: -5 }, body: { size: 10, align: 'justify', lineSpacing: 160, ratio: 90, spacing: -5 }, quote: { align: 'justify', lineSpacing: 160, ratio: 90, spacing: -5, marginLeft: 25 }, caption: { size: 10, align: 'justify', lineSpacing: 160, ratio: 90, spacing: -5 }, footnote: { size: 8, align: 'justify', lineSpacing: 140, ratio: 90, spacing: -5 }, refHead: { size: 11, bold: true, align: 'center', lineSpacing: 140, ratio: 90, spacing: -5 }, ref: { size: 9, align: 'justify', lineSpacing: 140, ratio: 90, spacing: -5, indent: -23, marginLeft: 23 }, dates: { size: 8, align: 'justify', lineSpacing: 140, ratio: 90, spacing: -5 } } },
